import java.io.BufferedReader;
import java.io.FileReader;
import java.util.ArrayList;

/**
 * A class to govern behavior of the various CSV Readers (one for plants, animals, scenarios, and habitats).
 * This class implements the actual "reading from a .csv file behavior" behaviour.
 *
 * @version 2022.02.28
 */
public abstract class CSVReader
{
    /**
     * Empty constructor for this class.
     */
    public CSVReader()
    {
    }

    /**
     * Method to be called by children, it centralizes the CSV Readers operations by
     * orchestrating the process of reading data from the .csv file and populating
     * the appropriate fields with the read data.
     *
     * @param nameOfElementToLookFor (String) the name of the element which data must be extracted
     */
    public void extractDataFor(String nameOfElementToLookFor)
    {
        resetParameters();
        String[] extractedData = getDataFor(nameOfElementToLookFor);
        if (extractedData != null) {
            populateFields(extractedData);
        } else {
            System.out.println("ERROR: no data could be read for " + nameOfElementToLookFor);
        }
    }

    /**
     * Reads the data relative to a given element in the appropriate .csv file
     * (the path to this file depends on the children class from which this method is called)
     * Source: technique to read .csv files was found on https://stackabuse.com/reading-and-writing-csvs-in-java/
     *
     * @param nameOfElementToLookFor (String) the name of the element which data must be extracted
     * @return (String[]) the extracted data
     */
    private String[] getDataFor(String nameOfElementToLookFor)
    {
        try(BufferedReader br = new BufferedReader(new FileReader(getFileName()))) {
            // Skip first line as they are headers.
            String line = br.readLine();
            while ((line=br.readLine()) != null) {
                String[] attributes = line.split(",");
                if (attributes[0].equals(nameOfElementToLookFor)) {
                    return attributes;
                }
            }
        } catch (Exception e) {
            System.out.println("Issue when parsing CSV");
        }
        return null;
    }

    /**
     * Abstract method that must be overridden with the appropriate behaviours
     * needed to populate the fields of the child class.
     *
     * @param extractedData (String[]) The data extracted from the .csv file.
     */
    abstract void populateFields(String[] extractedData);

    /**
     * Abstract method used to reset all the fields of a CSV Reader object when
     * the reading is done and another element ca be expected to be read.
     */
    abstract void resetParameters();

    /**
     * Abstract method to return the name of the file containing the data to be read.
     *
     * @return (String) the file name.
     */
    abstract String getFileName();

    /**
     * Returns a list of choices (of animals, habitats, and scenarios depending
     * on the child class it is called from) available to the user.
     * Source: technique to read from .csv files was found on https://stackabuse.com/reading-and-writing-csvs-in-java/
     *
     * @return (ArrayList<String>) The list of available choices.
     */
    public ArrayList<String> getChoicesList()
    {
        ArrayList<String> choicesList = new ArrayList<>();
        try(BufferedReader br = new BufferedReader(new FileReader(getFileName()))) {
            // Skip first line as they are headers.
            String line = br.readLine();
            while ((line=br.readLine()) != null) {
                String[] attributes = line.split(",");
                choicesList.add(attributes[0]);
            }
        } catch (Exception e) {
            e.printStackTrace();
            System.out.println("Issue when parsing CSV");
            return null;
        }
        return choicesList;
    }
}

import java.util.List;

/**
 * A class representing plants in the simulation. It extends
 * the abstract class Species
 *
 * @version 2022.02.28
 */
public class Plant extends Species
{
    // The plant's maximum health
    private int maxHealth;
    // The probability that the plant's health grows
    private static final double GROWING_PROBABILITY = 0.1;
    // Keep track of the plant's health
    private int currentHealth;
    // true if the current season is Spring
    private boolean isSpring;
    // true if the plant can regrow, needs at least one season till it is true again
    private boolean canRegrow;
    // true if plant appears dead due to temperature circumstances
    private boolean deadDueTemperature;

    /**
     * Create an instance of Plant
     *
     * @param field (Field) The field currently occupied.
     * @param location (Location) The location within the field.
     * @param name (String) The name of the plant
     * @param maximumTemperature (int) The maximum temperature that the plant can withstand
     * @param minimumTemperature (int) The minimum temperature that the plant can withstand
     * @param nutritionalValue (int) The nutritional value given to the specie that eats this plant
     * @param reproductionProbability (double) The probability that this plant will reproduce
     * @param maxHealth (int) The plant's maximum health
     */
    public Plant(Field field, Location location, String name, int maximumTemperature, int minimumTemperature, int nutritionalValue, double reproductionProbability, int maxHealth)
    {
        super(field, location, name, maximumTemperature, minimumTemperature, nutritionalValue, reproductionProbability);
        this.maxHealth = maxHealth;
        currentHealth = maxHealth;
        isSpring = true;
        canRegrow = true;
        deadDueTemperature = false;
    }

    /**
     * Imitate a plant's step by doing the following:
     * 1) if the plant can't survive the temperature, then it dies
     * 2) else if the time is day:
     *      i) if the plant is dead, and it's spring, and the temperature is suitable,
     *         then grow back
     *      ii) else if the plant is alive, then
     *          a) increase max health by 1 if it lived for a year
     *          b) reproduce and grow
     *
     * @param newPlants (List<Species>) A list to return the new plants created.
     * @param isNight (boolean) true if it is night in the simulation
     * @param temperature (int) The current temperature of the simulation
     * @param yearPassed (boolean) True if a year has passed in the simulation
     */
    public void act(List<Species> newPlants, boolean isNight, int temperature, boolean yearPassed)
    {
        // 1)
        if (! deadDueTemperature && ! survivesTemperature(temperature))
        {
            setDead();
        }
        // 2)
        else if (! isNight)
        {
            // i)
            if (deadDueTemperature && survivesTemperature(temperature) && isSpring) {
                regrow();
            }
            // ii)
            else if (! deadDueTemperature) {
                // a)
                if (yearPassed) {
                    maxHealth++;
                }
                // b)
                reproduce(newPlants);
                grow();
            }
        }
    }

    /**
     * Add a new plant in a free neighbouring location if the two
     * following conditions are met:
     * 1- The production probability meets the random number
     * 2- There is a free adjacent location.
     *
     * @param newPlants (list<Species>)A list to return the new plant
     */
    protected void reproduce(List<Species> newPlants)
    {
        if (rand.nextDouble() <= getReproductionProbability())
        {
            Field field = getField();
            if (field != null)
            {
                List<Location> free = field.getFreeAdjacentLocations(getLocation());

                if (free.size() > 0) {
                    Location loc = free.remove(0);
                    Plant newPlant = new Plant(field, loc, getName(), getMaximumTemperature(), getMinimumTemperature(), getNutritionalValue(), getReproductionProbability(), maxHealth);
                    newPlant.setIsSpring(isSpring);
                    newPlants.add(newPlant);
                }
            }
        }
    }

    /**
     * The plant dies because of the temperature or because it was eaten.
     * Its location in the field is cleared, but it still remembers its field and location
     */
    protected void setDead()
    {
        if(getLocation() != null) {
            deadDueTemperature = true;
            canRegrow = false; // set to false because if left as true, it could regrow the next step
            getField().clear(getLocation());
        }
    }

    /**
     * The dead plant is placed back in the field if its previous location is empty and can regrow, otherwise do nothing.
     * If it grows, then it grows back to full health.
     */
    private void regrow()
    {
        if(getField().getObjectAt(getLocation()) == null && canRegrow)   {
            deadDueTemperature = false;
            getField().place(this, getLocation());
            currentHealth = maxHealth;
        }
    }

    /**
     * Increase the plant's health by one if the random number meets the growing probability
     */
    private void grow()
    {
        if (currentHealth < maxHealth && rand.nextDouble() <= GROWING_PROBABILITY) {
            currentHealth++;
        }
    }

    /**
     * The effect of getting eaten by an animal.
     * Decrement currentHealth by one, and set dead if the current health is less than 1.
     */
    public void isEaten()
    {
        currentHealth--;

        if (currentHealth <= 0)    {
            super.setDead();
        }
    }

    /**
     * If isSpring is true, then change it to false, vice versa.
     *Also, set canRegrow as true because at least a season has passed since the plant died.
     */
    public void toggleIsSpring()
    {
        isSpring = ! isSpring;
        canRegrow = true;
    }

    /**
     * @return (boolean) true if the current season is spring, false otherwise.
     */
    public boolean getIsSpring()
    {
        return isSpring;
    }

    /**
     * Set the isSpring value to the given parameter
     *
     * @param spring (boolean) true if it is spring, false otherwise.
     */
    private void setIsSpring(boolean spring)
    {
        isSpring = spring;
    }
}

import java.util.List;
import java.util.ArrayList;
import java.util.Iterator;

/**
 * This is the main class of the simulation, as it connects all the other classes
 * and runs the simulation. In general, the classes simulate a habitat in which
 * there are preys who feed on plants, and predators who compete for the preys.
 *
 * @version 2022.02.28
 */
public class Simulator
{
    private static final int LONG_SIMULATION_STEP_COUNT = 2000;
    // List of species in the field.
    private List<Species> species;
    // The current state of the field.
    private Field field;
    // keep track of the simulation steps.
    private SimulationStep simStep;
    // A graphical view of the simulation.
    private SimulatorView view;
    // keep track of the time in the simulation
    private Time time;
    // the habitat of the simulation
    private Habitat simulationHabitat;
    private boolean simulationIsOn;

    private static final int DEFAULT_DELAY = 0;

    /**
     * Construct a simulation field with default size.
     */
    public Simulator(Habitat simulationHabitat, Time time, List<Species> speciesInSimulation, Field field, SimulationStep simulationStepCounter, SimulatorView simulatorView)
    {
        this.simulationHabitat = simulationHabitat;
        this.time = time;
        this.species = speciesInSimulation;
        this.field = field;
        this.simStep = simulationStepCounter;
        this.view = simulatorView;
        this.simulationIsOn = true;

        view.showStatus(simStep.getCurrentStep(), time.timeString(), simulationHabitat.getCurrentSeason(), simulationHabitat.getCurrentTemperature(), field);
    }


    /**
     * Run the simulation from its current state for a reasonably long period set as a class constant.
     */
    public void runLongSimulation()
    {
        simulate(LONG_SIMULATION_STEP_COUNT);
    }

    public void runHundredSteps()
    {
        simulate(100);
    }

    /**
     * Run the simulation from its current state for the given number of steps.
     * Stop before the given number of steps if it ceases to be viable.
     *
     * @param numSteps (int) The number of steps to run for.
     */
    public void simulate(int numSteps)
    {
        for(int step = 1; step <= numSteps && view.isViable(field); step++) {
            delay(DEFAULT_DELAY);
            simulateOneStep();
            // delay(200);   // uncomment this to run more slowly
        }
    }

    /**
     * Run the simulation from its current state for a single step.
     * Iterate over the whole field updating the state of each specie.
     */
    public void simulateOneStep()
    {
        if (simulationIsOn) {
            simStep.incStep();
            simulationHabitat.habitatStep();
            time.timeStep();

            // the following variables are added here to reduce method calls:
            boolean isSpring = simulationHabitat.getIsSpring();
            boolean isNight = time.getIsNight();
            int currentTemperature = simulationHabitat.getCurrentTemperature();
            boolean yearPassed = simulationHabitat.yearPassed();

            // Provide space for newborn species.
            List<Species> newSpecies = new ArrayList<>();
            // Let all species act.
            for(Iterator<Species> it = species.iterator(); it.hasNext(); )
            {
                Species specie = it.next();
                // Update the status of isSpring in the plants (done here to reduce coupling)
                if (specie instanceof Plant)
                {
                    Plant tempPlant = (Plant) specie;
                    if (tempPlant.getIsSpring() != isSpring) {
                        tempPlant.toggleIsSpring();
                    }
                }

                specie.act(newSpecies, isNight, currentTemperature, yearPassed);
                if(! specie.isAlive()) {
                    it.remove();
                }
            }

            // Add the newly born species to the main lists.
            species.addAll(newSpecies);
            view.showStatus(simStep.getCurrentStep(), time.timeString(), simulationHabitat.getCurrentSeason(), simulationHabitat.getCurrentTemperature(), field);
        }
    }

    /**
     * Reset the simulation to a starting position.
     */
    public void endSimulation()
    {
        simStep.reset();
        species.clear();
        simulationIsOn = false;
    }

    /**
     * Pause for a given time.
     * @param millisec (int) The time to pause for, in milliseconds
     */
    private void delay(int millisec)
    {
        try {
            Thread.sleep(millisec);
        }
        catch (InterruptedException ie) {
            // wake up
        }
    }
}

import java.util.ArrayList;
import java.util.List;
import java.util.Iterator;

/**
 * A class representing shared characteristics of animals,
 * could be initialised for prey animals.
 *
 * @version 2022.02.28
 */

public class Animal extends Species
{
    // Fields defining a special kind of animal, they can not be changed after initialization

    // The age at which an animal can start to breed.
    private final int breedingAge;
    // The age to which an animal can live.
    private final int maxAge;
    // The maximum number of births at once.
    private final int maxLitterSize;
    // true if the animal's sex if female
    private final boolean isFemale;
    // true if the animal hibernates during cold temperatures
    private final boolean hibernates;
    // true if the animal is active at night
    private final boolean isNocturnal;
    // the number of steps that should pass until an animal in hibernation moves
    private static final int STAY_STEPS = 10;

    // Fields prone to change during the animal's life

    // The animal's food level
    protected int foodLevel;
    // number of steps where the animal is in hibernation
    private int hiberSteps;
    // true if the animal is currently hibernating
    private boolean inHibernation;
    // The animal's age.
    private int age;

    /**
     * Create a new animal with given specifications. An animal can be created with random age (or start at age 0) and
     * with a random foodLevel.
     *
     * @param field (Field) the field where the simulation takes place
     * @param location (Location) the Location at which the animal should appear
     * @param name (String) the animal's name (its species' name)
     * @param maximumTemperature (int) the maximum temperature the animal can survive to
     * @param minimumTemperature (int) the minimum temperature an animal can survive to
     * @param nutritionalValue (int) the animal's nutritional value
     * @param reproductionProbability (double) the probability that the animal reproduces at each step after a given minimum breeding age
     * @param maxAge (int) the animal's life expectancy
     * @param breedingAge (int) the age at which animal can start to reproduce
     * @param maxLitterSize (int) the maximum number of children the animal can have in one reproduction
     * @param randomAge (boolean) whether an animal should be created with a random age
     * @param hibernates (boolean) whether an animal is able to hibernate
     * @param isNocturnal (boolean) whether an animal is more active at night
     */
    public Animal(Field field, Location location, String name, int maximumTemperature, int minimumTemperature, int nutritionalValue, double reproductionProbability, int maxAge, int breedingAge, int maxLitterSize, boolean randomAge, boolean hibernates, boolean isNocturnal)
    {
        super(field, location, name, maximumTemperature, minimumTemperature, nutritionalValue, reproductionProbability);

        this.breedingAge = breedingAge;
        this.maxAge = maxAge;
        this.maxLitterSize = maxLitterSize;
        this.isFemale = randomSex();
        this.hibernates = hibernates;
        this.isNocturnal = isNocturnal;
        // Default value is nutritionalValue to simulate the nutriment apart from the mother's milk/ other parental feeding.
        this.foodLevel = randomFoodLevel();
        inHibernation = false;
        hiberSteps = 0;

        if (randomAge) {
            age = rand.nextInt(maxAge);
        } else {
            age = 0;
        }
    }

    /**
     * Imitate an animal's step by doing the following:
     * 1) increment the animal's age if a year has passed.
     * 2) if the animal is alive, then:
     *      i) check if the animal should hibernate.
     *      ii) if the animal is in hibernation, then:
     *          a) if it passed STAY_STEPS steps without moving, then move and increment hunger.
     *          b) increment hiberSteps.
     *      iii) if the animal can't withstand the current temperature, then it dies.
     *      iv) if the animal is not in hibernation, then:
     *          a) if it is night and the animal is nocturnal, then move.
     *          b) if it is day, then all animals move and increment hunger.
     *
     * @param newSpecies (List<Species>) A list to receive newly born animals.
     * @param isNight (boolean) true if it is night in the simulation
     * @param temperature (int) the current temperature of the simulation
     * @param yearPassed true if a year has passed in the simulation
     */
    public void act(List<Species> newSpecies, boolean isNight, int temperature, boolean yearPassed)
    {
        // 1)
        if (yearPassed) {
            incrementAge();
        }

        // 2)
        if(isAlive())
        {
            // i)
            checkHibernation(temperature);

            // ii)
            if (inHibernation)
            {
                // a)
                if (hiberSteps % STAY_STEPS == 0)   {
                    makeMove(newSpecies);
                    incrementHunger();
                }
                // b)
                incrementHiberSteps();
            }
            // iii)
            else if (! survivesTemperature(temperature))
            {
                setDead();
            }
            // iv)
            else
            {
                // a)
                if (isNight && isNocturnal) {
                    makeMove(newSpecies);
                }
                // b)
                else if (! isNight) {
                    makeMove(newSpecies);
                }
                if  (! isNight) {
                    incrementHunger();
                }
            }
        }
    }

    /**
     * An animal's movement. It first tries to reproduce, then to eat if a plant is in one of the neighboring cells and finally to move
     * if an adjacent cell is available. If no adjacent cell is available, it dies of overcrowding.
     *
     * @param newSpecies (List<Species>) A list to receive newly born animals.
     */
    protected void makeMove(List<Species> newSpecies)
    {
        ArrayList<Animal> neighboringAnimalsList = getNeighboringAnimalsList();

        if (canReproduce(neighboringAnimalsList)) {
            reproduce(newSpecies);
        }

        // Eats if it is possible
        if (isNotFull()) {
            findFoodAndEat();
        }

        // Find a free location in adjacent cells
        Location newLocation = getField().freeAdjacentLocation(getLocation());

        // See if it was possible to move.
        if(newLocation != null) {
            setLocation(newLocation);
        }
        else {
            // Overcrowding.
            setDead();
        }
    }

    /**
     * Returns a list of animals located in neighboring cells.
     *
     * @return (ArrayList) list of neighboring animals
     */
    protected ArrayList<Animal> getNeighboringAnimalsList()
    {
        Field field = getField();
        List<Location> adjacent = field.adjacentLocations(getLocation());
        Iterator<Location> locationIterator = adjacent.iterator();

        ArrayList<Animal> neighboringAnimals = new ArrayList<>();
        while (locationIterator.hasNext())
        {
            Location where = locationIterator.next();
            Object species = field.getObjectAt(where);

            if (species instanceof Animal) {
                Animal neighboringAnimal = (Animal) species;
                if (neighboringAnimal.isAlive()) {
                    neighboringAnimals.add(neighboringAnimal);
                }
            }
        }
        return neighboringAnimals;
    }

    /**
     * Increase the age. This could result in the animal's death.
     */
    protected void incrementAge()
    {
        age++;
        if(age > maxAge) {
            setDead();
        }
    }

    /**
     * Make this animal more hungry. This could result in the animal's death.
     */
    protected void incrementHunger()
    {
        foodLevel--;
        if(foodLevel <= 0) {
            setDead();
        }
    }

    /**
     * @return (boolean) true if the animal is not full and therefore can eat and false if it is full.
     */
    protected boolean isNotFull()
    {
        return foodLevel < getNutritionalValue()*1.5;
    }

    /**
     * Increment hiberSteps by 1
     */
    protected void incrementHiberSteps()
    {

        hiberSteps++;
    }

    /**
     * Look for plants adjacent to the current location.
     * Only the first plant is eaten.
     */
    private void findFoodAndEat()
    {
        Field field = getField();
        List<Location> adjacent = field.adjacentLocations(getLocation());
        Iterator<Location> it = adjacent.iterator();

        while(it.hasNext())
        {
            Location where = it.next();
            Object species = field.getObjectAt(where); // change in Field
            if(species instanceof Plant)
            {
                Plant plantSquare = (Plant) species;
                if(plantSquare.isAlive()) {
                    plantSquare.isEaten();
                    incrementFoodLevel(plantSquare.getNutritionalValue());
                    break;
                }
            }
        }
    }

    /**
     * If the animal is a female, check if a male of the same species is in one of the neighboring cells. If it is the case, animal is able to reproduce
     *  and should go to the cel where the male is.
     *  Note: The task of reproducing is handled only by females so that the same reproduction can not happen twice in the same simulator step.
     *
     * @param  neighboringAnimalsList (ArrayList<Animal>) Array List of the Animal objects located in neighboring cells.
     * @return (boolean) if animal can reproduce.
     *
     */
    protected boolean canReproduce(ArrayList<Animal> neighboringAnimalsList)
    {
        // task to reproduce is handed to women only so that the same reproduction does not happen twice
        if (this.isFemale)
        {
            for (Animal neighbor : neighboringAnimalsList) {
                if (!neighbor.isFemale && neighbor.getName().equals(this.getName())) {
                    // The neighbor is a male of the same species
                    return true;
                }
            }
        }
        return false;
    }

    /**
     * Creates the appropriate number of animals of the same species. These new animals of course share the same features as their "parent"
     * except the sex which is randomized,  their age and foodLevel are not randomized.
     *
     * @param  speciesInSimulation (List<Species>) List of Species objects in the simulation for the newborns to be added to it.
     */
    protected void reproduce(List<Species> speciesInSimulation)
    {
        Field field = getField();
        if (field != null)
        {
            List<Location> free = field.getFreeAdjacentLocations(getLocation());
            int births = numberOfBirths();
            for(int b = 0; b < births && free.size() > 0; b++) {
                Location loc = free.remove(0);
                Animal young = new Animal(field, loc, getName(), getMaximumTemperature(), getMinimumTemperature(), getNutritionalValue(), getReproductionProbability(), maxAge, breedingAge, maxLitterSize,false, hibernates, isNocturnal);
                speciesInSimulation.add(young);
            }
        }
    }

    /**
     * Returns a random boolean to randomize the sex of newborns.
     *
     * @return true if female, otherwise false (male)
     */
    private boolean randomSex()
    {
        return Math.random() <= 0.5;
    }

    /**
     * Return a random foodLevel more than the animal's nutritional value divided by half.
     *
     * @return (int) the foodLevel.
     */
    private int randomFoodLevel()
    {
        int lowBound = getNutritionalValue()/2;
        return rand.nextInt(lowBound) + lowBound;
    }

    /**
     * Generate a number representing the number of births, if it can breed.
     *
     * @return (int) The number of births (can be zero).
     */
    protected int numberOfBirths()
    {
        int births = 0;
        if(canGiveBirth() && rand.nextDouble() <= getReproductionProbability()) {
            births = rand.nextInt(maxLitterSize) + 1;
        }
        return births;
    }

    /**
     * An animal can give birth if it has reached the minimal breeding age.
     */
    protected boolean canGiveBirth()
    {
        return age >= breedingAge;
    }

    /**
     * Check if the animal should be in hibernation.
     *
     * Change inHibernation to true if the animal can hibernate
     * and the current temperature is less than or equal the
     * minimum temperature of the animal + 5
     *
     * @param currentTemperature (int) the current temperature of the simulation
     */
    protected void checkHibernation(int currentTemperature)
    {
        if (hibernates && currentTemperature <= getMinimumTemperature() + 5)  {
            inHibernation = true;
        }
        else {
            inHibernation = false;
            hiberSteps = 0;
        }
    }

    /**
     * @return (int) The maximum age to which an animal can live
     */
    protected int getMaxAge ()
    {
        return maxAge;
    }

    /**
     * @return (int) The age at which an animal can start to breed
     */
    protected int getBreedingAge ()
    {
        return breedingAge;
    }

    /**
     * @return (int) The maximum number of births at once
     */
    protected int getMaxLitterSize ()
    {
        return maxLitterSize;
    }

    /**
     * @return (boolean) true if the animal hibernates
     */
    protected boolean getHibernates()
    {
        return hibernates;
    }

    /**
     * @return (boolean) true if the animal is active at night
     */
    protected boolean getIsNocturnal()
    {
        return isNocturnal;
    }

    /**
     * Increments the animal's food level by a given number (the nutritional value of the food he just ate).
     * It is public because a predator's food level can be incremented another predator in the case that it attacks it.
     *
     * @param value (int) the number to increment foodLevel by.
     */
    public void incrementFoodLevel(int value) {
        foodLevel += value;
    }

}

import java.util.List;
import java.util.Random;

/**
 * This is an abstract class representing all the species of
 * the simulation. It defines some characteristics and methods
 * of the species.
 *
 * @version 2022.02.28
 */
public abstract class Species
{
    // The probability for an individual to die if exposed to too high or too cold temperatures. Can be adjusted for simulation realism purposes.
    private static final double DYING_OF_COLD_OR_HEAT_PROBABILITY = 0.8;
    // Whether the species is alive or not.
    private boolean alive;
    // The animal's field.
    private Field field;
    // The species' position in the field.
    private Location location;
    // The species' name
    private final String name;
    // The maximum temperature at which the species can survive
    private final int maximumTemperature;
    // The minimum temperature at which the species can survive
    private final int minimumTemperature;
    // The food value animal provides when eaten
    private final int nutritionalValue;
    // The likelihood of a specie to reproduce.
    private final double reproductionProbability;
    // A random number generator
    protected static final Random rand = Randomizer.getRandom();

    /**
     * Create a new specie at location in field.
     *
     * @param field (Field) The field currently occupied.
     * @param location (Location) The location within the field.
     * @param name (String) The name of the specie
     * @param maximumTemperature (int) The maximum temperature that the specie can withstand
     * @param minimumTemperature (int) The minimum temperature that the specie can withstand
     * @param nutritionalValue (int) The nutritional value given to the specie that eats this specie
     * @param reproductionProbability (double) The probability that this specie will reproduce
     */
    public Species(Field field, Location location, String name, int maximumTemperature, int minimumTemperature, int nutritionalValue, double reproductionProbability)
    {
        alive = true;
        this.field = field;
        setLocation(location);
        this.name = name;
        this.maximumTemperature = maximumTemperature;
        this.minimumTemperature = minimumTemperature;
        this.nutritionalValue = nutritionalValue;
        this.reproductionProbability = reproductionProbability;
    }

    /**
     * Make this animal act - that is: make it do whatever it wants/needs to do.
     *
     * @param newSpecies (List<Species>) A list to receive newly born animals.
     * @param isNight (boolean) If it is currently night.
     * @param yearPassed (boolean) If a year is passing on this step (next step is the first of a nw year).
     */
    abstract public void act(List<Species> newSpecies, boolean isNight, int temperature, boolean yearPassed);

    /**
     * An abstract class to enforce all subclasses to make their elements reproduce
     *
     * @param newOfThisKind List of Species objects in the simulation for the newborns to be added to it
     */
    abstract void reproduce(List<Species> newOfThisKind);

    /**
     * Check whether the animal is alive or not.
     *
     * @return (boolean) true if the animal is still alive.
     */
    protected boolean isAlive()
    {
        return alive;
    }

    /**
     * Indicate that the animal is no longer alive. It is removed from the field.
     */
    protected void setDead()
    {
        alive = false;
        if(location != null) {
            field.clear(location);
            location = null;
            field = null;
        }
    }

    /**
     * Return the animal's location.
     *
     * @return (Location)The animal's location.
     */
    protected Location getLocation()
    {
        return location;
    }

    /**
     * Place the animal at the new location in the given field.
     *
     * @param newLocation (Location) The animal's new location.
     */
    protected void setLocation(Location newLocation)
    {
        if(location  != null) {
            field.clear(location);
        }
        location = newLocation;
        field.place(this, newLocation);
    }

    /**
     * @return (Field) The animal's field.
     */
    protected Field getField()
    {
        return field;
    }

    /**
     * Check if animal can survive the current temperature. If temperature is too low or too high, animal has a high probability of dying
     * (probability defined as a class constant to allow easy adjusting).
     *
     * @return (Field) The animal's field.
     */
    protected boolean survivesTemperature(int temperature)
    {
        if (temperature > maximumTemperature || temperature < minimumTemperature) {
            return Math.random() <= DYING_OF_COLD_OR_HEAT_PROBABILITY;
        }
        return true;
    }

    /**
     * @return (String) The specie's name.
     */
    protected String getName()
    {
        return name;
    }

    /**
     * @return (int) The maximum temperature specie can survive to.
     */
    protected int getMaximumTemperature()
    {
        return maximumTemperature;
    }

    /**
     * @return (int) The minimum temperature specie can survive to.
     */
    protected int getMinimumTemperature()
    {
        return minimumTemperature;
    }

    /**
     * @return (int) The specie's nutritional value.
     */
    protected int getNutritionalValue()
    {
        return nutritionalValue;
    }

    /**
     * @return (double) The specie's reproduction probability.
     */
    protected double getReproductionProbability()
    {
        return reproductionProbability;
    }

}

import java.util.List;
import java.util.ArrayList;

/**
 * A class representing the characteristics of a predator.
 * They are different from other animals because they eat any other
 * animal or predator whose strength is weaker.
 *
 * A horde of weaker predators can kill and eat a stronger predator.
 *
 *
 * @version 2022.03.01
 */
public class Predator extends Animal
{
    // The predator's strength, if it is strong enough it can attack other predators
    private final int strength;

    /**
     * Create a new predator with given specifications.
     *
     * @param strength (int) the predator's strength
     * @param field (Field) the field where the simulation takes place
     * @param location (Location) the Location at which the predator should appear
     * @param name (String) the predator's name (its species' name)
     * @param maximumTemperature (int) the maximum temperature the predator can survive to
     * @param minimumTemperature (int) the minimum temperature an predator can survive to
     * @param nutritionalValue (int) the predator's nutritional value
     * @param reproductionProbability (double) the probability that the predator reproduces at each step after a given minimum breeding age
     * @param maxAge (int) the predator's life expectancy
     * @param breedingAge (int) the age at which predator can start to reproduce
     * @param maxLitterSize (int) the maximum number of children the predator can have in one reproduction
     * @param randomAge (boolean) whether or not predator should be created with a random age
     * @param hibernates (boolean) whether or not predator is able to hibernate
     * @param isNocturnal (boolean) whether or not predator is more active at night
     */
    public Predator (int strength, Field field, Location location, String name, int maximumTemperature, int minimumTemperature, int nutritionalValue, double reproductionProbability, int maxAge, int breedingAge, int maxLitterSize,  boolean randomAge, boolean hibernates, boolean isNocturnal)
    {
        // call to the constructor of the Animal class
        super(field, location, name, maximumTemperature, minimumTemperature, nutritionalValue, reproductionProbability, maxAge, breedingAge, maxLitterSize, randomAge, hibernates, isNocturnal);

        this.strength = strength;
    }

    /**
     * A predator's movement. It first checks if it attacked by a horde of another species of predators. If it is the case,
     * it dies and execution stops. If not, it first tries to reproduce, then to find a prey to eat in the neighboring cells,
     * and finally to move to either the cell the prey he ate was occupying or another free adjacent cell. If no adjacent cell
     * is available, it dies of overcrowding.
     *
     * @param newSpecies (List<Species>) A list to receive newly born animals.
     */
    protected void makeMove(List<Species> newSpecies)
    {
        ArrayList<Animal> neighboringAnimals = getNeighboringAnimalsList();
        checkForAttack(neighboringAnimals);

        if (isAlive()) {
            if (canReproduce(neighboringAnimals)){
                reproduce(newSpecies);
            }

            // Move towards a source of food if found.
            Location newLocation = null;
            if (isNotFull()) {
                newLocation = findFoodAndEat(neighboringAnimals);
            } 

            if(newLocation == null) {
                // No food found - try to move to a free location.
                newLocation = getField().freeAdjacentLocation(getLocation());
            }

            // See if it was possible to move.
            if(newLocation != null) {
                setLocation(newLocation);
            }
            else {
                // Overcrowding.
                setDead();
            }
        }
    }

    /**
     * Tries to find a prey in one of the neighboring cell. If a prey is found, it is eaten and its location is returned.
     *
     * @param  neighboringAnimals (ArrayList<Animal>) A list of neighboring animals.
     * @return (Location) the location of the eaten prey, null if no prey was found.
     */
    private Location findFoodAndEat(ArrayList<Animal> neighboringAnimals)
    {
        for (Animal animal : neighboringAnimals) {
            if(!(animal instanceof Predator)){
                animal.setDead();
                foodLevel += animal.getNutritionalValue();
                return animal.getLocation();
            }
        }
        // No food found
        return null;
    }

    /**
     * Check if predator if under attack from a horde of another species of predator. If a horde is attacking it and the horde's strength
     * is greater than the predator's one, the horde members eat it.
     *
     * @param  neighboringAnimals (ArrayList<Animal>) A list of neighboring animals.
     */
    private void checkForAttack(ArrayList<Animal> neighboringAnimals)
    {
        ArrayList<Predator> hordeMembers = new ArrayList<>();

        for (int i =0; i < neighboringAnimals.size(); i++)
        {
            if (neighboringAnimals.get(i) instanceof Predator) {

                Predator neighboringPredator = (Predator)neighboringAnimals.get(i);
                String nameOfInvestigatedHorde = neighboringPredator.getName();

                if(! this.getName().equals(nameOfInvestigatedHorde))
                {
                    int totalHordeStrength =  neighboringPredator.getStrength();

                    hordeMembers.add(neighboringPredator);
                    for (int j =0; j < neighboringAnimals.size(); j++) {
                        if (nameOfInvestigatedHorde.equals(neighboringAnimals.get(j).getName())) {
                            Predator predatorObject = (Predator)neighboringAnimals.get(i);
                            totalHordeStrength += predatorObject.getStrength();
                            hordeMembers.add(predatorObject);
                        }
                    }
                    if (totalHordeStrength > strength) {
                        attackedByHorde(hordeMembers);
                        break;
                    } else {
                        hordeMembers.clear();
                    }
                }
            }
        }
    }

    /**
     * Animal is under attack by a horde whose strength is greater than its own. It is eaten by the horde and dies. Its nutritional value
     * is therefore shared
     *
     * @param hordeMembers (ArrayList<Predator>) List of the predators constituting the horde.
     */
    private void attackedByHorde(ArrayList<Predator> hordeMembers)
    {
        // Sharing predator's nutritional value amongst the various horde members.
        int foodLevelAddedToEachHordeMember = this.getNutritionalValue() / hordeMembers.size();
        for (Predator predator : hordeMembers) {
            predator.incrementFoodLevel(foodLevelAddedToEachHordeMember);
        }
        this.setDead();
    }

    /**
     * Creates the appropriate number of predators of the same species due to reproduction. These new predators of course share the same
     * features as their "parent" except the sex which is randomized, their age and foodLevel are not randomized.
     *
     * @param newOfThisKind (List<Species>) The list of species to which newborns must be added.
     */
    protected void reproduce(List<Species> newOfThisKind)
    {
        Field field = getField();
        if (field != null)
        {
            List<Location> free = field.getFreeAdjacentLocations(getLocation());
            int births = numberOfBirths();
            for(int b = 0; b < births && free.size() > 0; b++) {
                Location loc = free.remove(0);
                Predator young = new Predator(strength, field, loc, getName(), getMaximumTemperature(), getMinimumTemperature(), getNutritionalValue(), getReproductionProbability(), getMaxAge(), getBreedingAge(), getMaxLitterSize(),false, getHibernates(), getIsNocturnal());
                newOfThisKind.add(young);
            }
        }
    }

    /**
     * Returns the predator's strength, public so that other predators can consult the strength of a pontential horde this predator could
     * be a part of.
     *
     * @return (int) the predator's strength.
     */
    public int getStrength() {
        return strength;
    }
}

import java.awt.Color;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.HashMap;
import java.util.List;
import java.util.Random;

/**
 * Initializing the simulation. It first launches the UI, then builds the appropriate
 * objects to run the simulation desired by the user.
 *
 * IMPORTANT: This is the class that should be called to run the simulation.
 *
 * @version 2022.03.01
 */
public class Initializer
{
    // The default width for the grid.
    private static final int DEFAULT_WIDTH = 120;
    // The default depth of the grid.
    private static final int DEFAULT_DEPTH = 80;
    // The default color for plant objects.
    private static final Color DEFAULT_PLANT_COLOR = Color.decode("0x006400");
    // Default plant name, for now there is just one type of plant so its name is default, this can be changed as the rest of the code is extendable.
    private static final String DEFAULT_PLANT_NAME = "plant";
    // The default value of if animals' ages must be randomized when thy are created.
    private static final boolean RANDOM_ANIMAL_AGE = true;
    // The names of available climate change scenarios.
    private static final ArrayList<String> CLIMATE_CHANGE_SCENARIO_NAMES = new ArrayList<>(Arrays.asList("none", "low", "medium", "high"));
    // False of the simulation starts during the day, true if it starts during the night.
    private static final boolean DEFAULT_START_TIME = false;
    // The list of colors available for animal objects.
    private ArrayList<Color> listOfColorsForAnimals;
    // The index of the next color from the list used for an animal.
    private int idxOfColorToUseNext;
    // List of species to evolve in the field.
    private List<Species> speciesToEvolveInSimulation;
    // To read habitat related data.
    private final HabitatCSVReader habitatReader;
    // To read animal related data.
    private final AnimalCSVReader animalReader;
    // To read plant related data.
    private final PlantCSVReader plantReader;
    // A Random object to handle random behaviours throughout the class.
    private static final Random rand = Randomizer.getRandom();
    // A graphical view of the simulation.
    private SimulatorView view;
    // The plant concentration in the habitat created by the user.
    private double habitatPlantConcentration;
    // The GUIHandler handling the GUI.
    private GUIHandler handler;
    // Tool to alert user about any potential error.
    private ErrorThrower errorThrower;


    /**
     * Builds an Initializer object and initializes its field.
     */
    public Initializer()
    {
        speciesToEvolveInSimulation = new ArrayList<>();
        habitatReader = new HabitatCSVReader();
        animalReader = new AnimalCSVReader();
        plantReader = new PlantCSVReader();
        listOfColorsForAnimals = new ArrayList<>();
        errorThrower = new ErrorThrower();

        populateAnimalColors();
        idxOfColorToUseNext = 0;

        openGUI();
    }

    /**
     * Opens the GUI with the list of available animals and habitats extracted
     * from the files as well as the list of available climate change scenarios.
     */
    private void openGUI()
    {
        ArrayList<String> animalChoices = animalReader.getChoicesList();
        ArrayList<String> habitatChoices = habitatReader.getChoicesList();
        handler = new GUIHandler(this, animalChoices, habitatChoices, CLIMATE_CHANGE_SCENARIO_NAMES);
    }

    /**
     * Create a simulator with the animals, habitat, and climate change
     * scenario asked by the user as well as all other necessary objects
     * for the simulation to run. The created Simulator is returned.
     *
     * @param chosenHabitat (String) The name of the habitat chosen by the user.
     * @param animalsToCreate (HashMap<String, Integer>) Keys are the animals' names and values are the number of each animal we need to create.
     * @param scenarioName (String) The name of the climate change scenario to implement in the simulation.
     * @return (Simulator) The created simulator.
     */
    public Simulator initializeSimulation(String chosenHabitat, HashMap<String, Integer> animalsToCreate, String scenarioName)
    {
        SimulationStep simulatorStepCounter = new SimulationStep();
        Field field = new Field(DEFAULT_DEPTH, DEFAULT_WIDTH);
        ClimateScenarios chosenClimateChangeScenario = createChosenClimateChangeScenario(scenarioName);
        Habitat simulationHabitat = createHabitat(chosenHabitat, simulatorStepCounter, chosenClimateChangeScenario);
        if (getNumberOfPlants() + getNumberOfAnimals(animalsToCreate) > calculateFieldArea()) {
            errorThrower.throwMessage("Too many animals were added for this habitat, please reduce the number of animals and try again");
            return null;
        }
        view = new SimulatorView(DEFAULT_DEPTH, DEFAULT_WIDTH, handler);
        populateWithAnimals(animalsToCreate, field);
        populateWithPlants(field);
        Time timeObject = new Time(simulatorStepCounter, DEFAULT_START_TIME);
        return new Simulator(simulationHabitat, timeObject ,speciesToEvolveInSimulation, field, simulatorStepCounter, view);
    }

    /**
     * Read data for the chosen habitat and create a habitat object appropriately.
     *
     * @param habitatName (String) The name of the chosen habitat.
     * @param simulatorStepCounter (SimulationStep) The created SimulationStep object for this simulation to be handed to the Habitat object.
     * @param climateChangeScenario (ClimateScenarios) The created ClimateScenarios enum to be handed to the Habitat object.
     * @return (Habitat) the created Habitat object.
     */
    private Habitat createHabitat (String habitatName, SimulationStep simulatorStepCounter, ClimateScenarios climateChangeScenario)
    {
        if (habitatName != null) {
            habitatReader.extractDataFor(habitatName);
            Habitat chosenHabitat = new Habitat(simulatorStepCounter, climateChangeScenario ,habitatReader.getSpringTemperatures(), habitatReader.getSummerTemperatures(), habitatReader.getAutumnTemperatures(), habitatReader.getWinterTemperatures());
            habitatPlantConcentration = habitatReader.getPlantConcentration();
            return chosenHabitat;
        }
        else {
            errorThrower.throwMessage("Habitat name was not specified successfully.");
            return null;
        }
    }

    /**
     * Populate the simulation with the chosen animals.
     * First reading the data relating to each animal,
     * then creating and adding to the list of species the right number of each animal.
     *
     * @param animalsToCreate (HashMap<String, Integer>) The names and number of chosen animals.
     * @param field (Field) The field in which the animals will evolve.
     */
    private void populateWithAnimals(HashMap<String, Integer> animalsToCreate, Field field)
    {
        idxOfColorToUseNext = 0;
        Location freeLocationToPlaceAnimal;

        for(String animalName : animalsToCreate.keySet()) {
            animalReader.extractDataFor(animalName);
            if (animalsToCreate.get(animalName) != 0)
            {
                // Retrieve appropriate data.
                String name = animalReader.getName();
                int maximumTemperature = animalReader.getMaximumTemperature();
                int minimumTemperature = animalReader.getMinimumTemperature();
                int maxAge = animalReader.getMaximumAge();
                int breedingAge = animalReader.getBreedingAge();
                double breedingProbability = animalReader.getBreedingProbability();
                int maxLitterSize = animalReader.getMaxLitterSize();
                int nutritionalValue = animalReader.getNutritionalValue();
                boolean hibernates = animalReader.canHibernate();
                boolean isNocturnal = animalReader.isNocturnal();

                if (animalReader.isPredator()) {
                    // Predator object should be created, retrieving appropriate data.
                    int strength = animalReader.getStrength();

                    // Creating the right number of Predator objects.
                    for (int i = 0; i < animalsToCreate.get(animalName); i++) {
                        freeLocationToPlaceAnimal = findAvailableLocation(field);
                        Predator newPredator = new Predator(strength, field, freeLocationToPlaceAnimal, name, maximumTemperature, minimumTemperature, nutritionalValue, breedingProbability, maxAge, breedingAge, maxLitterSize, RANDOM_ANIMAL_AGE, hibernates, isNocturnal);
                        speciesToEvolveInSimulation.add(newPredator);
                    }
                }
                else {
                    // Animal object should be created
                    // Creating the right number of Animal objects.
                    for (int i = 0; i < animalsToCreate.get(animalName); i++) {
                        freeLocationToPlaceAnimal = findAvailableLocation(field);
                        Animal newAnimal = new Animal(field, freeLocationToPlaceAnimal, name, maximumTemperature, minimumTemperature, nutritionalValue, breedingProbability, maxAge, breedingAge, maxLitterSize, RANDOM_ANIMAL_AGE, hibernates, isNocturnal);
                        speciesToEvolveInSimulation.add(newAnimal);
                    }
                }

                // Setting the color for this species.
                view.setColor(name, listOfColorsForAnimals.get(idxOfColorToUseNext));
                idxOfColorToUseNext ++;
            }
        }
    }

    /**
     * Create the chosen climate change scenario. Scenarios are pre-defined in the enum ClimateScenarios
     * as their functions can be changed to better approximate the real scenarios projected by the GIEC.
     *
     * @param scenarioName (String) The name of the scenario chosen by the user.
     * @return (ClimateScenarios) The created ClimateScenarios enum.
     */
    private ClimateScenarios createChosenClimateChangeScenario(String scenarioName)
    {
        ClimateScenarios chosenScenario;
        if (scenarioName.equals(CLIMATE_CHANGE_SCENARIO_NAMES.get(3))) {
            chosenScenario = ClimateScenarios.SCENARIO4;
        }
        else if (scenarioName.equals(CLIMATE_CHANGE_SCENARIO_NAMES.get(2))) {
            chosenScenario = ClimateScenarios.SCENARIO3;
        }
        else if (scenarioName.equals(CLIMATE_CHANGE_SCENARIO_NAMES.get(1))) {
            chosenScenario = ClimateScenarios.SCENARIO2;
        }
        else{
            chosenScenario = ClimateScenarios.SCENARIO1;
        }
        return chosenScenario;
    }

    /**
     * Find an available location for an object to be created in the simulation field.
     * The simulation is chosen at random and is changed if the randomly selected cell
     * already contains an object.
     *
     * @param field (Field) The simulation's field.
     * @return (Location) the available location found.
     */
    private Location findAvailableLocation(Field field)
    {
        int randomWidth = rand.nextInt(DEFAULT_WIDTH);
        int randomDepth = rand.nextInt(DEFAULT_DEPTH);
        while (field.getObjectAt(randomDepth,randomWidth) != null) {
            randomWidth = rand.nextInt(DEFAULT_WIDTH);
            randomDepth = rand.nextInt(DEFAULT_DEPTH);
        }
        return new Location(randomDepth, randomWidth);
    }

    /**
     * Calculate the area of the field to know the number of plants that should be created.
     *
     * @return (int) The field's area.
     */
    private int calculateFieldArea()
    {
        return DEFAULT_WIDTH * DEFAULT_DEPTH;
    }

